import { readdirSync } from "fs";
const dir = "/synthetic/repo/plugin/adapters/_shared/src";
const root = "/synthetic/repo";
const skip = new Set(["runTrackerProjectMilestoneAttachedProbe","runMarkerHelperInvokedPerGateProbe"]);
const files = readdirSync(dir).filter(f => f.endsWith(".ts") && !f.endsWith(".test.ts"));
let n=0, bad=[];
for (const f of files) {
  let m; try { m = await import(`${dir}/${f}`); } catch { continue; }
  for (const [k,v] of Object.entries(m)) {
    if (!/^run[A-Z].*Probe$/.test(k) || typeof v !== "function" || skip.has(k)) continue;
    n++;
    try {
      const r:any = await (v as any)(root);
      const viol = r?.violations ?? [];
      const errs = viol.filter((x:any)=> (x.severity ?? "error") === "error");
      const notes = r?.notes ?? [];
      console.log(`${k}: ok=${r?.ok} violations=${viol.length} errors=${errs.length} notes=${Array.isArray(notes)?notes.length:notes} vacuous=${r?.vacuous}`);
      if (viol.length) bad.push([k, viol.map((x:any)=>x.note ?? x.message)]);
    } catch (e:any) { console.log(`${k}: THREW ${e.message}`); bad.push([k, e.message]); }
  }
}
console.log("total", n); console.log(JSON.stringify(bad,null,1));
EOF
bun run probes.ts 2>&1 | tail -120

